  "question_restated": "Did the rain on Wednesday 2024-07-31 change taxi demand or where people took taxis, compared with dry Tuesday 2024-07-30?",
  "metric": "total_valid_trips_per_day with hourly normalization (trips/hour) to account for any partial-day effects; also trip counts by zone and airport association",
  "focus": "Wednesday 2024-07-31 (rainy) vs Tuesday 2024-07-30 (dry), both with full 24-hour coverage, comparing total trips, hourly rates, zone-level destination shifts, and airport trip shares",
  "baseline": "Tuesday 2024-07-30 as the dry comparator (24h coverage, 102,477 trips). Also compare to Monday 2024-07-29 (87,840 trips) for trend context. Hourly rates normalized to trips/hour to isolate weather effect from coverage differences.",
  "hypotheses": [
    {
      "id": "H1",
      "claim": "Rain on 2024-07-31 reduced total taxi demand compared to the dry 2024-07-30, even after hourly normalization, because inclement weather suppresses trip generation.",
      "test": "SELECT pickup_date, COUNT(*) AS trips, COUNT(DISTINCT pickup_hour) AS hours_covered, ROUND(COUNT(*)/NULLIF(COUNT(DISTINCT pickup_hour),0),1) AS trips_per_hour FROM investigator.trips WHERE pickup_date IN ('2024-07-30','2024-07-31') AND is_valid_trip GROUP BY pickup_date"
    },
    {
      "id": "H2",
      "claim": "Rain on 2024-07-31 shifted trip destinations toward nearer/zones or away from high-distance airport trips, changing the geographic distribution even if total trip count is similar.",
      "test": "SELECT pickup_date, dropoff_zone, COUNT(*) AS dropoff_count FROM investigator.trips WHERE pickup_date IN ('2024-07-30','2024-07-31') AND is_valid_trip GROUP BY pickup_date, dropoff_zone ORDER BY pickup_date, dropoff_count DESC LIMIT 20"
    },
    {
      "id": "H3",
      "claim": "Rain on 2024-07-31 disproportionately reduced airport-related trips (JFK/LaGuardia/Newark) compared to other trip types, dragging down overall demand because airport trips normally drive high volume.",
      "test": "SELECT pickup_date, SUM(CASE WHEN pickup_zone IN ('JFK Airport','LaGuardia Airport','Newark Airport') OR dropoff_zone IN ('JFK Airport','LaGuardia Airport','Newark Airport') THEN 1 ELSE 0 END) AS airport_trips, COUNT(*) AS total_trips FROM investigator.trips WHERE pickup_date IN ('2024-07-30','2024-07-31') AND is_valid_trip GROUP BY pickup_date"
    }
  ],
  "memory_used": ["data_quality"]
}

